using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;

// Provided infrastructure — do not modify.
public interface IFetcher
{
    string[] Fetch();
}

public sealed class InMemoryFetcher : IFetcher
{
    public System.Collections.Generic.List<string> Rows = new();
    public string[] Fetch() => Rows.ToArray();
}

